-- Minimal fixture for the existing schema. Admin migration is executed unchanged.
create role anon; create role authenticated; create role service_role;
create schema private;
create table public.riders(rider_id uuid primary key,full_name text,first_name text,last_name text,contact_number text,
 employment_status text default 'active',availability_status text default 'online',vehicle_type text default 'motorcycle',
 maximum_active_deliveries integer default 1,capacity_kg numeric default 50,handling_capability_keys text[] default '{}',logistics_company_id bigint);
create table public.farmers(farmer_user_id bigint primary key,phone_number text);
create table public.farms(farm_id bigint primary key,farmer_user_id bigint,farm_location text,gps_lat numeric,gps_long numeric);
create table public.buyers(buyer_user_id bigint primary key);
create table public.carts(cart_id bigint primary key,buyer_user_id bigint);
create table public.commodities(commodity_id bigint primary key,commodity_name text,farm_id bigint);
create table public.cart_items(cart_item_id bigint primary key,cart_id bigint,commodity_id bigint,quantity numeric);
create table public.orders(order_id bigint primary key,seller_farm_id bigint,cart_item_id bigint,client_order_id text,
 buyer_name_snapshot text,order_status text,delivery_address text,delivery_latitude double precision,delivery_longitude double precision,
 contact_number text,total_amount numeric,payment_method text default 'gcash',payment_status text default 'verified',delivery_date date,updated_at timestamptz);
create table public.deliveries(delivery_id bigint generated by default as identity primary key,order_id bigint,delivery_status text default 'available',
 created_at timestamptz default now(),estimated_delivery_time timestamptz,actual_delivery_time timestamptz,pickup_location text,dropoff_location text,
 distance_km numeric,vehicle_types text,cold_chain_available boolean,delivery_deadline timestamptz);
create table public.logistics_companies(logistics_company_id bigint primary key,cod_available boolean);
create table private.seller_order_registry(buyer_user_id bigint,seller_farm_id bigint,seller_order_id text);
create table private.order_delivery_fulfillments(fulfillment_id bigint generated always as identity primary key,buyer_user_id bigint,
 seller_order_id text,representative_order_id bigint unique,delivery_id bigint unique references public.deliveries(delivery_id),
 pickup_lat double precision,pickup_long double precision,dropoff_lat double precision,dropoff_long double precision,
 pickup_contact text,dropoff_contact text,total_weight_kg numeric,required_vehicle_type text,handling_notes text);
create table private.rider_delivery_assignments(delivery_id bigint primary key references public.deliveries(delivery_id),rider_id uuid references public.riders(rider_id),assigned_at timestamptz default now());
create table private.delivery_status_events(delivery_id bigint references public.deliveries(delivery_id),idempotency_key text,
 previous_status text,new_status text,remarks text,latitude double precision,longitude double precision,changed_at timestamptz default now(),primary key(delivery_id,idempotency_key));
create table public.rider_assignment_requests(request_id uuid default gen_random_uuid(),delivery_id bigint,seller_order_id text,rider_id uuid,farmer_user_id bigint,
 status text default 'pending',requested_schedule timestamptz,expires_at timestamptz,requested_at timestamptz default now(),responded_at timestamptz,updated_at timestamptz,failure_reason text);
create unique index requests_pending on public.rider_assignment_requests(delivery_id) where status='pending';
create unique index requests_accepted on public.rider_assignment_requests(delivery_id) where status='accepted';
create table public.delivery_proofs(proof_id uuid default gen_random_uuid(),delivery_id bigint,proof_stage text,proof_type text,file_path text,
 confirmation_code_hash text,remarks text,confirmed_at timestamptz,created_at timestamptz default now());
create function private.require_delivery_evidence_before_completion() returns trigger language plpgsql as $$
begin
 if new.delivery_status='completed' and old.delivery_status is distinct from 'completed'
   and coalesce(current_setting('app.admin_delivery_completion_override',true),'')<>'on'
   and not exists(select 1 from public.delivery_proofs p where p.delivery_id=new.delivery_id and p.proof_stage='delivery' and p.proof_type='photo' and nullif(trim(p.file_path),'') is not null)
 then raise exception 'A delivery evidence photo is required before completion' using errcode='22023'; end if;
 return new;
end $$;
create trigger deliveries_require_completion_evidence before update of delivery_status on public.deliveries for each row execute function private.require_delivery_evidence_before_completion();
create table public.rider_locations(rider_id uuid primary key references public.riders(rider_id),latitude double precision,longitude double precision,
 accuracy_meters double precision,location_updated_at timestamptz default now());
-- Same ownership contract as the rider app's policies; no admin migration changes it.
alter table public.rider_locations enable row level security;
grant select,insert,update on public.rider_locations to authenticated;
create policy rider_own_location on public.rider_locations to authenticated
 using(rider_id=current_setting('test.rider_id',true)::uuid) with check(rider_id=current_setting('test.rider_id',true)::uuid);

